#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# M1 acceptance (e): the reusable release workflows, run for real from the fixture
# app repo passpier/rnship-s6-probe (the single fixture repo from now on). It checks:
#   E1  the caller pins both workflows to a 40-char rn-ship-pipeline SHA
#   E2  your push to main publishes a staging EAS Update
#   E3  ...and uploads its source maps to Sentry
#   E4  a PR opened by the broker's App runs PR checks with EXPO_TOKEN absent
#   E5  a push to main by the App skips the staging job (actor gate)
#   E6  your re-run of that App push is skipped too (triggering_actor)
# Run as YOUR macOS user, from a rn-ship-pipeline checkout of main, pushed to origin.
# Results land in docs/spikes/M1e.results.env (gitignored). Secrets go only
# to GitHub Actions secrets, never to disk.

ROOT=$(cd "$(dirname "$0")/../.." && pwd)
REPO=passpier/rnship-s6-probe
PIPELINE=passpier/rn-ship-pipeline
RELEASE_ACTOR=passpier
EAS="npx -y eas-cli@24.13.0" # the version the staging workflow pins
WORK=${RNSHIP_FIXTURE_DIR:-$HOME/Home_Projects/rnship-s6-probe}
TOKEN_SH=$ROOT/scripts/spikes/s0-app-token.sh
S0_RESULTS=$ROOT/docs/spikes/S0.results.env
ENV_FILE=$ROOT/docs/spikes/M1e.results.env

trap 'warn "stopped at line $LINENO. Fix the cause and re-run; finished stages are safe to repeat."' ERR

record() { write_env "$1" "$2"; }
fail() { warn "$1"; exit 1; }
s0_value() { sed -n "s/^$1=//p" "$S0_RESULTS" | tail -n1; }

# app_token PERMS_JSON mints a 1-hour App token for $REPO only (s0-app-token.sh).
app_token() {
  RNSHIP_APP_ID=$APP_ID RNSHIP_APP_INSTALLATION_ID=$APP_INSTALLATION_ID \
    "$TOKEN_SH" mint "$REPO" "$1" 2>/dev/null | jq -r '.token // empty'
}
# git_app ARGS... is git with the App token $T only, as the broker runs it: your
# credential helpers and global config are off.
git_app() {
  GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null GIT_TERMINAL_PROMPT=0 \
  GIT_CONFIG_COUNT=2 \
  GIT_CONFIG_KEY_0=credential.helper GIT_CONFIG_VALUE_0= \
  GIT_CONFIG_KEY_1=http.https://github.com/.extraheader \
  GIT_CONFIG_VALUE_1="AUTHORIZATION: basic $(printf 'x-access-token:%s' "$T" | base64)" \
    git "$@"
}
gh_app() { GH_TOKEN=$T gh "$@"; } # never falls back to your login

# wait_run SHA EVENT [ATTEMPT] prints the id of the completed "rnship" run for SHA,
# or nothing after 15 minutes.
wait_run() {
  local id="" status="" i
  for i in $(seq 180); do
    id=$(gh api "repos/$REPO/actions/runs?head_sha=$1&event=$2" \
      --jq '[.workflow_runs[] | select(.name == "rnship")][0].id // empty' 2>/dev/null || true)
    if [[ -n "$id" ]]; then
      status=$(gh api "repos/$REPO/actions/runs/$id${3:+/attempts/$3}" --jq .status 2>/dev/null || true)
      [[ "$status" == completed ]] && { echo "$id"; return; }
    fi
    (( i % 12 == 0 )) && note "still waiting ($((i * 5))s)…" >&2
    sleep 5
  done
}
# jobs_of RUN [ATTEMPT] prints "job=conclusion" lines.
jobs_of() {
  gh api "repos/$REPO/actions/runs/$1${2:+/attempts/$2}/jobs" --jq '.jobs[] | "\(.name)=\(.conclusion)"'
}
# conclusion_of RUN PREFIX [ATTEMPT]: conclusion of the job whose name starts with PREFIX.
conclusion_of() { jobs_of "$1" "${3:-}" | sed -n "s/^$2[^=]*=//p" | head -n1; }
step_conclusion() {
  gh api "repos/$REPO/actions/runs/$1/jobs" \
    --jq ".jobs[].steps[]? | select(.name == \"$2\") | .conclusion" | head -n1
}
show_jobs() { jobs_of "$@" | sed 's/^/    /'; }
has_secret() { gh secret list -R "$REPO" --json name --jq '.[].name' 2>/dev/null | grep -qx "$1"; }

TOTAL_STAGES=8

banner "M1 (e): release workflows on the fixture repo"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
[[ $EUID -ne 0 && "$(id -un)" != rnship-agent ]] || fail "run this as your own macOS user"
for c in gh jq git node npx openssl security; do
  command -v "$c" >/dev/null || fail "missing $c"
done
node -e 'process.exit(+process.versions.node.split(".")[0] >= 24 ? 0 : 1)' || fail "need Node 24 (nvm use 24)"
gh auth status >/dev/null 2>&1 || fail "gh isn't logged in: gh auth login"
[[ "$(gh api user --jq .login)" == "$RELEASE_ACTOR" ]] || fail "gh must be logged in as $RELEASE_ACTOR"

# The actor gate has to be on origin/main, and the App token helper in this checkout.
gh api "repos/$PIPELINE/contents/.github/workflows/release-staging-ota.yml?ref=main" --jq .content \
  | base64 -d | grep -q 'release-actor' || fail "the actor gate isn't on origin/main: git push origin main"
[[ -x "$TOKEN_SH" ]] || fail "no $TOKEN_SH: git switch main && git pull"
[[ "$(gh repo view "$PIPELINE" --json visibility --jq .visibility)" == PUBLIC ]] \
  || fail "$PIPELINE is private: the fixture repo can't call its workflows"
[[ "$(gh repo view "$REPO" --json visibility --jq .visibility)" == PRIVATE ]] || fail "$REPO should be private"

[[ -f "$S0_RESULTS" ]] || fail "no $S0_RESULTS: the App id comes from the S0 run"
APP_ID=$(s0_value S0_APP_ID); APP_INSTALLATION_ID=$(s0_value S0_APP_INSTALLATION_ID); APP_SLUG=$(s0_value S0_APP_SLUG)
[[ -n "$APP_ID" && -n "$APP_INSTALLATION_ID" ]] || fail "S0 results lack the App id"
T=$(app_token '{"contents":"read"}'); [[ -n "$T" ]] || fail "couldn't mint an App token for $REPO (keychain item rnship-broker-app?)"
gh_app api -X DELETE /installation/token >/dev/null 2>&1 || true; T=""

RNSHIP_SHA=$(gh api "repos/$PIPELINE/commits/main" --jq .sha)
record M1E_RNSHIP_SHA "$RNSHIP_SHA"
say "Workflows will be pinned to $PIPELINE@$RNSHIP_SHA."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Clean up the S0 leftovers in $REPO"
OPEN_PRS=$(gh pr list -R "$REPO" --state open --json number --jq '.[].number' | tr '\n' ' ')
BRANCHES=$(gh api "repos/$REPO/branches" --paginate --jq '.[].name | select(. != "main")' | tr '\n' ' ')
say "This turns $REPO into the fixture app repo:"
step "close open PRs: ${OPEN_PRS:-none}"
step "delete branches: ${BRANCHES:-none}"
step "remove the S0 probe workflow and test files (in the next push)"
step "set the repo's default GITHUB_TOKEN to read-only, unable to approve PRs"
confirm "Go ahead? (closing PRs and deleting branches can't be undone)" || fail "stopped; nothing changed"
for n in $OPEN_PRS; do gh pr close "$n" -R "$REPO" -c "Closed by the M1 (e) wizard: S0 leftovers." >/dev/null; done
for b in $BRANCHES; do gh api -X DELETE "repos/$REPO/git/refs/heads/$b" >/dev/null; done
gh api -X PUT "repos/$REPO/actions/permissions/workflow" \
  -f default_workflow_permissions=read -F can_approve_pull_request_reviews=false
record M1E_DEFAULT_TOKEN "$(gh api "repos/$REPO/actions/permissions/workflow" \
  --jq '"\(.default_workflow_permissions),\(.can_approve_pull_request_reviews)"')"

if [[ -d "$WORK/.git" ]]; then
  git -C "$WORK" fetch -q origin && git -C "$WORK" switch -q main && git -C "$WORK" reset -q --hard origin/main
else
  gh repo clone "$REPO" "$WORK" -- -q
fi
git -C "$WORK" rm -rq --ignore-unmatch g1.txt g4.txt s0-control.txt .github/workflows/s0-probe.yml
say "Local checkout: $WORK"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Expo: log in and create EXPO_TOKEN"
cd "$WORK"
if ! $EAS whoami >/dev/null 2>&1; then
  say "Log eas-cli in with your Expo account (sign up at expo.dev first if you need to)."
  $EAS login
fi
EXPO_ACCOUNT=$($EAS whoami 2>/dev/null | head -n1)
record M1E_EXPO_ACCOUNT "$EXPO_ACCOUNT"
if has_secret EXPO_TOKEN && ! confirm "$REPO already has EXPO_TOKEN. Replace it?"; then
  note "keeping the existing EXPO_TOKEN"
else
  open_url "https://expo.dev/settings/access-tokens"
  step "Click 'Create token', name it rnship-fixture-ci, and copy the token."
  note "It can publish production updates too (D1), so it goes only into the push-to-main job."
  ask_secret EXPO_TOKEN "Paste the token:"
  [[ -n "$EXPO_TOKEN" ]] || fail "no token"
  EXPO_TOKEN=$EXPO_TOKEN $EAS whoami >/dev/null 2>&1 || fail "that token doesn't authenticate"
  set_secret EXPO_TOKEN "$EXPO_TOKEN"
  EXPO_TOKEN=""
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Sentry: project and auth token"
open_url "https://sentry.io/signup/"
step "Sign up or log in (the free Developer plan is enough)."
step "Create a project: platform React Native, name rnship-fixture."
note "The org slug is the subdomain in the URL: https://<org>.sentry.io/…"
ask SENTRY_ORG "Org slug:"
ask SENTRY_PROJECT "Project slug [rnship-fixture]:"
SENTRY_PROJECT=${SENTRY_PROJECT:-rnship-fixture}
record SENTRY_ORG "$SENTRY_ORG"
record SENTRY_PROJECT "$SENTRY_PROJECT"
if has_secret SENTRY_AUTH_TOKEN && ! confirm "$REPO already has SENTRY_AUTH_TOKEN. Replace it?"; then
  note "keeping the existing SENTRY_AUTH_TOKEN"
else
  open_url "https://$SENTRY_ORG.sentry.io/settings/auth-tokens/"
  step "Settings → Organization Tokens → Create New Token, name it rnship-fixture-ci, copy it (starts sntrys_)."
  note "If that page doesn't load, open Settings in Sentry's sidebar and find Organization Tokens there."
  ask_secret SENTRY_AUTH_TOKEN "Paste the token:"
  [[ -n "$SENTRY_AUTH_TOKEN" ]] || fail "no token"
  set_secret SENTRY_AUTH_TOKEN "$SENTRY_AUTH_TOKEN"
  SENTRY_AUTH_TOKEN=""
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Expo skeleton (SDK 57, TypeScript) and the rnship caller"
if [[ ! -f "$WORK/package.json" ]]; then
  TMP=$(mktemp -d)
  npx -y create-expo-app@latest "$TMP/app" --template blank-typescript --no-install --no-agents-md
  rsync -a --exclude .git "$TMP/app/" "$WORK/" # never the template's own .git
  rm -rf "$TMP"
  npm install --no-audit --no-fund
  npx expo install expo-updates @sentry/react-native
fi
[[ -n "$(node -p 'require("./app.json").expo.extra?.eas?.projectId ?? ""')" ]] || $EAS init --force --non-interactive
$EAS update:configure --platform all --non-interactive

# Fingerprint runtime policy (plan D3); the Sentry plugin names org and project.
SENTRY_ORG=$SENTRY_ORG SENTRY_PROJECT=$SENTRY_PROJECT node -e '
const fs = require("fs");
const j = JSON.parse(fs.readFileSync("app.json", "utf8"));
const sentry = ["@sentry/react-native/expo", { url: "https://sentry.io/", organization: process.env.SENTRY_ORG, project: process.env.SENTRY_PROJECT }];
j.expo.runtimeVersion = { policy: "fingerprint" };
j.expo.plugins = (j.expo.plugins ?? []).filter((p) => !String(Array.isArray(p) ? p[0] : p).startsWith("@sentry/react-native")).concat([sentry]);
fs.writeFileSync("app.json", JSON.stringify(j, null, 2) + "\n");'
cat > metro.config.js <<'JS'
// Sentry's serializer adds Debug IDs to bundles and source maps (Sentry Expo guide).
const { getSentryExpoConfig } = require('@sentry/react-native/metro');

module.exports = getSentryExpoConfig(__dirname);
JS
mkdir -p .github/workflows
cat > .github/workflows/rnship.yml <<YAML
# Calls rn-ship-pipeline's reusable workflows, pinned by SHA (release/README.md).
name: rnship
on:
  pull_request:
  push:
    branches: [main]
permissions:
  contents: read
jobs:
  pr-checks:
    if: github.event_name == 'pull_request'
    uses: $PIPELINE/.github/workflows/release-pr-checks.yml@$RNSHIP_SHA
    with:
      rnship-sha: $RNSHIP_SHA
      validate-command: npx tsc --noEmit
    # No secrets here, and never secrets: inherit.
  staging-ota:
    if: github.event_name == 'push' && github.ref == 'refs/heads/main'
    uses: $PIPELINE/.github/workflows/release-staging-ota.yml@$RNSHIP_SHA
    with:
      release-actor: $RELEASE_ACTOR
      sentry-org: $SENTRY_ORG
      sentry-project: $SENTRY_PROJECT
    secrets:
      EXPO_TOKEN: \${{ secrets.EXPO_TOKEN }}
      SENTRY_AUTH_TOKEN: \${{ secrets.SENTRY_AUTH_TOKEN }}
YAML
printf '# rnship fixture app\n\nThe fixture Expo app for rn-ship-pipeline acceptance runs (M1 e, M3–M5). Private: identifiers here stay out of the public repo.\n' > README.md

say "Local checks (the same ones the PR checks run):"
npx tsc --noEmit && note "tsc ok"
npx expo-doctor || warn "expo-doctor reported problems: the PR check will too. Fix, or continue and see."
record M1E_E1_PINNED_BY_SHA "$(grep -cE "@[0-9a-f]{40}\$" .github/workflows/rnship.yml | grep -qx 2 && echo yes || echo no)"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Your push to main → staging OTA + source maps"
git add -A
git commit -qm "Fixture: Expo SDK 57 skeleton, rnship caller pinned to ${RNSHIP_SHA:0:12}" || note "nothing new to commit"
date +%s > .rnship-e-push && git add .rnship-e-push && git commit -qm "M1 (e): push by you"
git push -q origin HEAD:main
YOUR_SHA=$(git rev-parse HEAD)
note "waiting for the rnship run on ${YOUR_SHA:0:12} (npm ci + eas update take a few minutes)…"
RUN=$(wait_run "$YOUR_SHA" push)
[[ -n "$RUN" ]] || fail "no completed run after 15 min: https://github.com/$REPO/actions"
show_jobs "$RUN"
record M1E_E2_RUN "https://github.com/$REPO/actions/runs/$RUN"
record M1E_E2_STAGING_ON_YOUR_PUSH "$(conclusion_of "$RUN" staging-ota)"
record M1E_E2_UPDATE_GROUP "$(gh run view "$RUN" -R "$REPO" --log 2>/dev/null | sed -n 's/.*update group \([^ ]*\) from.*/\1/p' | head -n1)"
record M1E_E3_SENTRY_UPLOAD "$(step_conclusion "$RUN" 'Upload source maps to Sentry')"
note "Wanted: staging success, an update group id, Sentry upload success."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "A PR opened by the broker's App → PR checks without EXPO_TOKEN"
T=$(app_token '{"contents":"write","pull_requests":"write"}'); [[ -n "$T" ]] || fail "couldn't mint an App token"
W=$(mktemp -d); B="agent/m1e-$(date +%s)"
git_app clone -q "https://github.com/$REPO.git" "$W/app"
git -C "$W/app" config user.name "$APP_SLUG[bot]"
git -C "$W/app" config user.email "$APP_SLUG[bot]@users.noreply.github.com"
git -C "$W/app" switch -qc "$B"
printf '\n// %s\n' "$B" >> "$W/app/App.tsx"
git -C "$W/app" commit -qam "M1 (e): JS-only change on $B"
git_app -C "$W/app" push -q origin "$B"
PR_N=$(gh_app api -X POST "repos/$REPO/pulls" -f title="M1 (e): PR checks without EXPO_TOKEN" \
  -f head="$B" -f base=main -f body="Opened with the broker's App token by scripts/acceptance/m1e.sh." --jq .number)
PR_SHA=$(git -C "$W/app" rev-parse HEAD)
note "PR #$PR_N opened by $APP_SLUG[bot]; waiting for its checks…"
RUN=$(wait_run "$PR_SHA" pull_request)
[[ -n "$RUN" ]] || fail "no completed PR run after 15 min"
show_jobs "$RUN"
record M1E_E4_RUN "https://github.com/$REPO/actions/runs/$RUN"
record M1E_E4_PR_CHECKS "$(conclusion_of "$RUN" pr-checks)"
record M1E_E4_EXPO_TOKEN_ABSENT "$(gh run view "$RUN" -R "$REPO" --log 2>/dev/null | grep -q 'EXPO_TOKEN is absent' && echo yes || echo no)"
record M1E_E4_STAGING_ON_PR "$(conclusion_of "$RUN" staging-ota)"
gh pr close "$PR_N" -R "$REPO" --delete-branch -c "M1 (e) check done." >/dev/null || true
note "Wanted: pr-checks success, EXPO_TOKEN absent yes, staging skipped. PR closed again."
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "The App pushes straight to main → staging skipped"
say "The broker never does this; here the App token does it directly, as a compromised"
say "broker could (S0 G4). The actor gate must skip the staging job, and your re-run too."
git -C "$W/app" switch -q main
date +%s > "$W/app/.rnship-e-push"
git -C "$W/app" add -A && git -C "$W/app" commit -qm "M1 (e): push to main by the App"
git_app -C "$W/app" push -q origin HEAD:main
BOT_SHA=$(git -C "$W/app" rev-parse HEAD)
gh_app api -X DELETE /installation/token >/dev/null 2>&1 || true; T=""; rm -rf "$W"
RUN=$(wait_run "$BOT_SHA" push)
[[ -n "$RUN" ]] || fail "no completed run for the App's push after 15 min"
show_jobs "$RUN"
record M1E_E5_RUN "https://github.com/$REPO/actions/runs/$RUN"
record M1E_E5_ACTOR "$(gh api "repos/$REPO/actions/runs/$RUN" --jq .actor.login)"
record M1E_E5_STAGING_ON_APP_PUSH "$(conclusion_of "$RUN" staging-ota)"
note "re-running it as you…"
gh run rerun "$RUN" -R "$REPO" >/dev/null
RUN2=$(wait_run "$BOT_SHA" push 2)
[[ -n "$RUN2" ]] || fail "the re-run didn't complete"
record M1E_E6_STAGING_ON_YOUR_RERUN "$(conclusion_of "$RUN2" staging-ota 2)"
git -C "$WORK" pull -q --ff-only origin main || true

say ""
say "Results (also in docs/spikes/M1e.results.env):"
grep '^M1E_E' "$ENV_FILE" | sed 's/^/    /'
note "Wanted: E1 yes · E2 success + a group id · E3 success · E4 success, yes, skipped"
note "· E5 actor $APP_SLUG[bot], skipped · E6 skipped."
note "main now holds a commit by the App, so the next rnship merge approve will refuse"
note "until you vouch with --accept-main: that's backstop #3 doing its job."
pause "Press Enter for the summary"

finish
